mapper.select:
SELECT pan.*, fatherPanel.id AS parent_id, fatherPanel.NAME AS parent_name, IFNULL( chart.chartNum, 0 ) AS chart_num , IFNULL( sta.starred, 0 ) AS starred, pan.var_type as varType FROM visual_panel pan LEFT JOIN visual_panel fatherPanel ON pan.pid = fatherPanel.id LEFT JOIN ( SELECT panel_id, count( 1 ) AS chartNum FROM visual_chart GROUP BY panel_id ) chart ON pan.id = chart.panel_id LEFT JOIN ( SELECT IF(COUNT(1) > 0, 1, 0) AS starred,tid FROM sys_user_starred WHERE TYPE = "panel" AND uid = #{params.currentLoginUserID} GROUP BY tid) sta ON pan.id = sta.tid
and pan.id in
#{id}
and pan.type=#{params.type}
and pan.pid=#{params.pid}
and pan.link=#{params.link}
and pan.var_type=#{params.varType}
AND
starred = #{params.starred}
starred IS NULL
ORDER BY pan.id
ORDER BY pan.weight,pan.id

update.foreach:
UPDATE visual_panel

    weight = #{panel.weight},
    pid = #{panel.pid}

WHERE
id = #{panel.id}
